/**
 * اطلاعیه‌های حقوقی، فارسی (fa): پیش‌نویس‌های ساده و رسمی برای اطلاعیه پایه، بلوک‌های مخاطب و بلوک‌های حوزه قضایی.
 * هیچ مجوز، ثبت یا وضعیت نظارتی را ادعا نمی‌کنند. اطلاعات نهاد حقوقی جاینما است ({{legal_entity}}، {{registration}}، …):
 * بندی که جاینمای خالی دارد منتشر نمی‌شود و noticeTodos() آن را برای مالک فهرست می‌کند. بلوک‌های حوزه قضایی پیش‌نویس‌اند،
 * بازبینی مشاور حقوقی لازم دارند و تا تغییر وضعیتشان منتشر نمی‌شوند (../notices.js).
 *
 * Persian: formal-but-plain written copy. Built-in values: {{brand}}, {{site}}, {{domain}}.
 */
const NAMES = {
  IR: "ایران",
  SA: "عربستان سعودی",
  AE: "امارات متحده عربی",
  GB: "بریتانیا",
  EU: "اتحادیه اروپا و منطقه اقتصادی اروپا",
  US: "ایالات متحده آمریکا",
  SG: "سنگاپور",
  MY: "مالزی",
  ID: "اندونزی",
};

export const JURISDICTION = [
  "برای خوانندگانی که در {name} هستند: این محتوا فقط برای {{audience_{k}}} تهیه شده است و سایر اشخاص در {name} نباید به آن اتکا کنند.",
  "هیچ بخشی از این محتوا در {name} به منزله پیشنهاد، دعوت یا ترغیب به خرید، فروش یا پذیره‌نویسی هیچ محصول یا خدمتی یا انعقاد هیچ قراردادی نیست. ممکن است محصولات و قابلیت‌های معرفی‌شده در {name} در دسترس نباشند.",
  "{{regulatory_statement_{k}}}",
];

const fill = (t, v) => t.replace(/\{(\w+)\}/g, (m, k) => (k in v ? v[k] : m));

export const jurisdiction = (code, name) => {
  const k = code.toLowerCase();
  return { title: name, paragraphs: JURISDICTION.map((t) => fill(t, { name, k })) };
};

